def migrate(conn):
    def read_meta():
        rows = conn.execute('SELECT rowid, version FROM meta LIMIT 2').fetchall()
        if len(rows) != 1 or type(rows[0][1]) is not int:
            raise ValueError('meta must contain exactly one integer version')
        return rows[0]

    rowid, version = read_meta()
    if version == 2:
        return
    if version != 1:
        raise ValueError('unsupported schema version')

    conn.execute('BEGIN IMMEDIATE')
    try:
        current_rowid, current_version = read_meta()
        if current_rowid != rowid or current_version != 1:
            raise ValueError('schema version changed')
        conn.execute('CREATE TABLE bindings(id TEXT PRIMARY KEY, policy TEXT NOT NULL)')
        cursor = conn.execute(
            'UPDATE meta SET version = 2 WHERE rowid = ? AND version = 1',
            (rowid,),
        )
        if cursor.rowcount != 1:
            raise ValueError('expected exactly one updated meta row')
        conn.execute('COMMIT')
    except BaseException:
        conn.execute('ROLLBACK')
        raise
